--
-- Name: protect_executable_revision(); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.protect_executable_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' OR NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.resource_kind IS DISTINCT FROM OLD.resource_kind OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
    OR NEW.digest IS DISTINCT FROM OLD.digest OR NEW.snapshot IS DISTINCT FROM OLD.snapshot
    OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR (OLD.published_at IS NOT NULL AND (NEW.published_at IS DISTINCT FROM OLD.published_at OR NEW.published_by IS DISTINCT FROM OLD.published_by))
    OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
  THEN RAISE EXCEPTION 'Executable revisions are immutable' USING ERRCODE='55000'; END IF;
  RETURN NEW;
END $$;

--
-- Name: protect_execution_audit(); Type: FUNCTION; Schema: access; Owner: -
--

CREATE FUNCTION access.protect_execution_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Execution audit is append-only' USING ERRCODE='55000'; END $$;

--
-- Name: enqueue_openclaw_mcp_sync_agents(bigint[]); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_agents(agent_ids bigint[]) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO agent_mcp_sync_queue (agent_id)
    SELECT id FROM agents WHERE id = ANY(agent_ids) AND runtime_type = 'openclaw' AND deleted_at IS NULL
  ON CONFLICT (agent_id) DO UPDATE SET revision = agent_mcp_sync_queue.revision + 1,
    attempts = 0, retry_at = now(), error = NULL;
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_agent(); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_agent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY(
      SELECT id FROM agents WHERE id = NEW.id OR workspace_path = NEW.workspace_path));
  ELSE
    PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY(
      SELECT id FROM agents WHERE id = NEW.id OR workspace_path IN (OLD.workspace_path, NEW.workspace_path)));
  END IF;
  RETURN NULL;
END;
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_agent_row(); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_agent_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY[NEW.agent_id]);
  ELSIF TG_OP = 'DELETE' THEN PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY[OLD.agent_id]);
  ELSE PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY[OLD.agent_id, NEW.agent_id]);
  END IF;
  RETURN NULL;
END;
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_server(); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_server() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE server_id BIGINT := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
BEGIN
  PERFORM enqueue_openclaw_mcp_sync_agents(ARRAY(
    SELECT agent_id FROM agent_mcp_assignments WHERE mcp_server_id = server_id
    UNION
    SELECT tm.agent_id FROM team_mcp_assignments tma
      JOIN teams te ON te.id = tma.team_id
      JOIN team_members tm ON tm.team_id = te.id
    WHERE tma.mcp_server_id = server_id AND tma.enabled = 1 AND tm.enabled = 1
      AND te.enabled = 1 AND te.deleted_at IS NULL));
  RETURN NULL;
END;
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_team(bigint[]); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_team(team_ids bigint[]) RETURNS void
    LANGUAGE sql
    AS $$
  SELECT enqueue_openclaw_mcp_sync_agents(ARRAY(SELECT agent_id FROM team_members WHERE team_id = ANY(team_ids)));
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_team_assignment(); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_team_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN PERFORM enqueue_openclaw_mcp_sync_for_team(ARRAY[NEW.team_id]);
  ELSIF TG_OP = 'DELETE' THEN PERFORM enqueue_openclaw_mcp_sync_for_team(ARRAY[OLD.team_id]);
  ELSE PERFORM enqueue_openclaw_mcp_sync_for_team(ARRAY[OLD.team_id, NEW.team_id]);
  END IF;
  RETURN NULL;
END;
$$;

--
-- Name: enqueue_openclaw_mcp_sync_for_team_row(); Type: FUNCTION; Schema: agents; Owner: -
--

CREATE FUNCTION agents.enqueue_openclaw_mcp_sync_for_team_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM enqueue_openclaw_mcp_sync_for_team(ARRAY[NEW.id]);
  RETURN NULL;
END;
$$;

--
-- Name: telemetry_capture_change(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_capture_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  old_row jsonb := '{}'::jsonb; new_row jsonb := '{}'::jsonb; row_data jsonb;
  old_safe jsonb := '{}'::jsonb; new_safe jsonb := '{}'::jsonb; task_row jsonb; instance_row jsonb;
  tenant bigint; task bigint; project bigint; workflow bigint; agent bigint; entity bigint;
  entity_kind text; event_kind text; key_text text; old_tenant bigint;
  now_at timestamptz := clock_timestamp(); happened_at timestamptz;
  payload_data jsonb; changed jsonb; outbox_id bigint; other_tenant bigint; affected_ids bigint[];
  supersedes_key text; previous_payload jsonb; previous_cause text; previous_time timestamptz;
  previous_project bigint; previous_workflow bigint; previous_agent bigint;
  config_keys text[] := ARRAY['id','key','name','status','status_key','label','terminal','is_default_entry',
    'stage_order','workflow_id','workflow_type','workflow_type_key','project_id','task_type','from_status',
    'to_status','outcome','outcome_key','field_name','requirement_type','match_field','severity','enabled',
    'priority','agent_id','source','event_name','action_kind','action_target','behavior','relationship_type_key',
    'category','affects_dispatch_eligibility','direction_semantics','active_statuses_json','resolved_statuses_json',
    'allowed_transitions_json','status_includes_json','status_excludes_json','model','instructions_version','runtime_type'];
BEGIN
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;
  row_data := CASE WHEN TG_OP = 'DELETE' THEN old_row ELSE new_row END;
  tenant := (row_data->>'tenant_id')::bigint;
  entity := (row_data->>'id')::bigint;
  task := COALESCE((row_data->>'task_id')::bigint,
    (row_data->>'source_task_id')::bigint,(row_data->>'blocked_id')::bigint);
  workflow := (row_data->>'workflow_id')::bigint;
  project := (row_data->>'project_id')::bigint;
  agent := (row_data->>'agent_id')::bigint;
  IF TG_TABLE_NAME='projects' THEN project:=entity;
  ELSIF TG_TABLE_NAME='workflows' THEN workflow:=entity;
  ELSIF TG_TABLE_NAME='agents' THEN agent:=entity; END IF;
  entity_kind := 'configuration';
  event_kind := 'configuration.changed';
  happened_at := now_at;

  IF TG_OP='DELETE' AND TG_TABLE_NAME IN ('job_instances','runtime_executions') THEN
    entity_kind := CASE TG_TABLE_NAME WHEN 'job_instances' THEN 'run' ELSE 'runtime_execution' END;
    tenant := COALESCE(tenant,(SELECT tenant_id FROM telemetry_outbox
      WHERE entity_type=entity_kind AND entity_id=entity LIMIT 1));
    DELETE FROM telemetry_outbox WHERE entity_type=entity_kind AND entity_id=entity;
    DELETE FROM telemetry_observations WHERE entity_type=entity_kind AND entity_id=entity;
    IF tenant IS NOT NULL AND to_regclass('telemetry.telemetry_query_results') IS NOT NULL THEN
      PERFORM telemetry_invalidate_source(tenant, TG_TABLE_NAME, entity, true);
    END IF;
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'task_statuses' THEN
    IF TG_OP='UPDATE' AND old_row->'terminal' IS NOT DISTINCT FROM new_row->'terminal'
      AND old_row->'name' IS NOT DISTINCT FROM new_row->'name' THEN RETURN NULL; END IF;
    SELECT array_agg(DISTINCT blocked_id) INTO affected_ids FROM task_dependencies;
    outbox_id := nextval(pg_get_serial_sequence('telemetry_outbox','id'));
    PERFORM telemetry_refresh_dependencies(affected_ids,'global-terminality:'||outbox_id,
      NULLIF(current_setting('agent_hq.telemetry_causation_id',true),''));
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'tasks' THEN
    task := entity;
    task_row := row_data;
    IF tenant IS NULL THEN SELECT tenant_id INTO tenant FROM workflows WHERE id = workflow; END IF;
    -- A hard deletion follows the canonical retention policy. Keep a minimal
    -- tombstone, never the deleted task's custom fields or frozen proof data.
    IF TG_OP = 'DELETE' THEN
      DELETE FROM telemetry_outbox WHERE task_id = task;
      DELETE FROM telemetry_observations WHERE task_id = task;
      IF to_regclass('telemetry.telemetry_query_results') IS NOT NULL THEN
        PERFORM telemetry_invalidate_source(tenant, TG_TABLE_NAME, entity, true);
      END IF;
      old_safe := jsonb_build_object('id',task);
    ELSE
      new_safe := telemetry_task_snapshot(new_row || jsonb_build_object('tenant_id',tenant));
      IF TG_OP = 'UPDATE' THEN
        old_safe := telemetry_task_snapshot(old_row || jsonb_build_object('tenant_id',COALESCE((old_row->>'tenant_id')::bigint,tenant)));
      END IF;
    END IF;
    entity_kind := 'task';
    event_kind := CASE TG_OP WHEN 'INSERT' THEN 'task.created' WHEN 'DELETE' THEN 'task.deleted' ELSE 'task.changed' END;
    old_tenant := (old_row->>'tenant_id')::bigint;
    IF old_tenant IS NOT NULL AND old_tenant <> tenant THEN
      DELETE FROM telemetry_outbox WHERE task_id = task;
      DELETE FROM telemetry_observations WHERE task_id = task;
      old_safe := '{}'::jsonb;
      event_kind := 'task.bootstrap';
    END IF;
  ELSIF TG_TABLE_NAME = 'job_instances' THEN
    entity_kind := 'run';
    event_kind := CASE TG_OP WHEN 'INSERT' THEN 'run.created' WHEN 'DELETE' THEN 'run.deleted' ELSE 'run.changed' END;
    IF TG_OP <> 'DELETE' THEN new_safe := telemetry_run_snapshot(new_row); END IF;
    IF TG_OP <> 'INSERT' THEN old_safe := telemetry_run_snapshot(old_row); END IF;
  ELSIF TG_TABLE_NAME = 'runtime_executions' THEN
    SELECT to_jsonb(j) INTO instance_row FROM job_instances j WHERE id = (row_data->>'instance_id')::bigint;
    task := (instance_row->>'task_id')::bigint;
    agent := (instance_row->>'agent_id')::bigint;
    entity_kind := 'runtime_execution';
    event_kind := CASE TG_OP WHEN 'INSERT' THEN 'runtime.created' WHEN 'DELETE' THEN 'runtime.deleted' ELSE 'runtime.changed' END;
    new_safe := telemetry_pick(new_row,ARRAY['id','instance_id','runtime_type','driver','backend','state',
      'boundary_version','boundary_fingerprint','started_at','ended_at','created_at']);
    old_safe := telemetry_pick(old_row,ARRAY['id','instance_id','runtime_type','driver','backend','state',
      'boundary_version','boundary_fingerprint','started_at','ended_at','created_at']);
    happened_at := telemetry_timestamp(row_data->>'ended_at',now_at);
  ELSIF TG_TABLE_NAME = 'task_history' THEN
    -- Canonical task mutations already capture status/fields. Only the accepted
    -- semantic outcome is distinct evidence; notes/error strings are excluded.
    IF row_data->>'field' <> 'lifecycle_outcome' OR TG_OP = 'DELETE' THEN RETURN NULL; END IF;
    entity_kind := 'task'; entity := task; event_kind := 'task.outcome';
    new_safe := jsonb_build_object('outcome',row_data->'new_value');
    old_safe := jsonb_build_object('outcome',old_row->'new_value');
  ELSIF TG_TABLE_NAME = 'external_task_event_receipts' THEN
    -- Only accepted receipts represent an event, not every request/retry.
    IF row_data->>'processing_state' NOT IN ('processed','applied','ignored','completed') OR TG_OP = 'DELETE' THEN RETURN NULL; END IF;
    entity_kind := 'task'; entity := task; event_kind := 'task.external_event';
    new_safe := telemetry_pick(new_row,ARRAY['source','event','processing_state','mapping_id','mapping_action_kind','mapping_action_target','fingerprint']);
    old_safe := telemetry_pick(old_row,ARRAY['source','event','processing_state','mapping_id','mapping_action_kind','mapping_action_target','fingerprint']);
  ELSIF TG_TABLE_NAME IN ('task_relationships','task_dependencies') THEN
    entity_kind := 'task'; entity := task;
    event_kind := CASE TG_OP WHEN 'INSERT' THEN 'task.relationship_added' WHEN 'DELETE' THEN 'task.relationship_removed' ELSE 'task.relationship_changed' END;
    new_safe := telemetry_pick(new_row,ARRAY['source_task_id','target_task_id','relationship_type_key','blocker_id','blocked_id']);
    old_safe := telemetry_pick(old_row,ARRAY['source_task_id','target_task_id','relationship_type_key','blocker_id','blocked_id']);
    SELECT tenant_id INTO other_tenant FROM tasks WHERE id = COALESCE((row_data->>'target_task_id')::bigint,(row_data->>'blocker_id')::bigint);
  ELSIF TG_TABLE_NAME = 'task_field_schemas' THEN
    new_safe := telemetry_pick(new_row,ARRAY['id','workflow_type_key','task_type']) || jsonb_build_object('schema',telemetry_schema_snapshot(new_row->>'schema_json'));
    old_safe := telemetry_pick(old_row,ARRAY['id','workflow_type_key','task_type']) || jsonb_build_object('schema',telemetry_schema_snapshot(old_row->>'schema_json'));
  ELSIF TG_TABLE_NAME = 'routing_config_audit_log' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NULL; END IF;
    workflow := (row_data->>'workflow_id')::bigint;
    new_safe := telemetry_pick(row_data,ARRAY['entity_table','entity_id','entity_key','action','workflow_type','workflow_id','batch_id']) ||
      jsonb_build_object('before_fingerprint',md5(row_data->>'before_json'),'after_fingerprint',md5(row_data->>'after_json'));
    old_safe := '{}'::jsonb;
  ELSE
    new_safe := telemetry_pick(new_row,config_keys);
    old_safe := telemetry_pick(old_row,config_keys);
    IF TG_TABLE_NAME = 'agents' THEN
      new_safe := new_safe || jsonb_build_object('instructions_fingerprint',md5(new_row->>'job_instructions'));
      old_safe := old_safe || jsonb_build_object('instructions_fingerprint',md5(old_row->>'job_instructions'));
    END IF;
    IF TG_OP = 'DELETE' AND TG_TABLE_NAME IN ('projects','workflows','agents') THEN
      -- Honor canonical entity retention, including historical run snapshots.
      IF TG_TABLE_NAME = 'projects' THEN
        DELETE FROM telemetry_outbox WHERE tenant_id=tenant AND project_id=entity;
        DELETE FROM telemetry_observations WHERE tenant_id=tenant AND project_id=entity;
        project := entity;
      ELSIF TG_TABLE_NAME = 'workflows' THEN
        DELETE FROM telemetry_outbox WHERE tenant_id=tenant AND workflow_id=entity;
        DELETE FROM telemetry_observations WHERE tenant_id=tenant AND workflow_id=entity;
        workflow := entity;
      ELSE
        DELETE FROM telemetry_outbox WHERE tenant_id=tenant AND
          ((agent_id=entity AND entity_type IN ('run','runtime_execution')) OR (source='agents' AND entity_id=entity));
        DELETE FROM telemetry_observations WHERE tenant_id=tenant AND
          ((agent_id=entity AND entity_type IN ('run','runtime_execution')) OR (source='agents' AND entity_id=entity));
      END IF;
      IF to_regclass('telemetry.telemetry_query_results') IS NOT NULL THEN
        PERFORM telemetry_invalidate_source(tenant, TG_TABLE_NAME, entity, true);
      END IF;
      old_safe := jsonb_build_object('id',entity);
      new_safe := '{}'::jsonb;
      event_kind := 'configuration.deleted';
    END IF;
  END IF;

  IF task IS NOT NULL AND task_row IS NULL THEN SELECT to_jsonb(t) INTO task_row FROM tasks t WHERE id = task; END IF;
  IF task_row IS NOT NULL THEN
    IF tenant IS NOT NULL AND (task_row->>'tenant_id')::bigint IS NOT NULL
      AND tenant <> (task_row->>'tenant_id')::bigint THEN RETURN NULL; END IF;
    tenant := COALESCE(tenant,(task_row->>'tenant_id')::bigint);
    project := (task_row->>'project_id')::bigint;
    workflow := (task_row->>'workflow_id')::bigint;
    agent := COALESCE(agent,(task_row->>'agent_id')::bigint);
  END IF;
  IF tenant IS NULL AND workflow IS NOT NULL THEN
    SELECT tenant_id,project_id INTO tenant,project FROM workflows WHERE id = workflow;
  END IF;
  IF tenant IS NULL AND project IS NOT NULL THEN SELECT tenant_id INTO tenant FROM projects WHERE id = project; END IF;
  IF task_row IS NULL AND agent IS NOT NULL AND entity_kind IN ('run','runtime_execution') THEN
    SELECT tenant_id,project_id INTO other_tenant,project FROM agents WHERE id=agent;
    IF tenant IS NOT NULL AND other_tenant IS DISTINCT FROM tenant THEN RETURN NULL; END IF;
    tenant := COALESCE(tenant,other_tenant);
  END IF;
  IF tenant IS NULL AND agent IS NOT NULL THEN SELECT tenant_id INTO tenant FROM agents WHERE id = agent; END IF;
  -- Global legacy configuration has no tenant owner. It is discoverable in the
  -- catalog, but cannot silently be assigned to an arbitrary tenant's history.
  IF tenant IS NULL OR NOT EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN RETURN NULL; END IF;
  IF other_tenant IS NOT NULL AND other_tenant <> tenant THEN RETURN NULL; END IF;
  -- Revoke only proofs whose recorded sources lost access. Same-project run
  -- linking preserves point-in-time results; metric filters run on recalculation.
  IF TG_OP='UPDATE' AND to_regclass('telemetry.telemetry_query_results') IS NOT NULL
    AND TG_TABLE_NAME IN ('tasks','agents','workflows','job_instances','runtime_executions')
    AND (old_row->'tenant_id' IS DISTINCT FROM new_row->'tenant_id'
      OR old_row->'project_id' IS DISTINCT FROM new_row->'project_id'
      OR old_row->'task_id' IS DISTINCT FROM new_row->'task_id'
      OR old_row->'agent_id' IS DISTINCT FROM new_row->'agent_id'
      OR old_row->'instance_id' IS DISTINCT FROM new_row->'instance_id') THEN
    PERFORM telemetry_invalidate_source(tenant, TG_TABLE_NAME, entity, false);
    IF (old_row->>'tenant_id')::bigint IS DISTINCT FROM tenant THEN
      PERFORM telemetry_invalidate_source((old_row->>'tenant_id')::bigint, TG_TABLE_NAME, entity, false);
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND old_safe = new_safe
    AND NOT (TG_TABLE_NAME='task_history' AND old_row->'created_at' IS DISTINCT FROM new_row->'created_at') THEN RETURN NULL; END IF;

  IF TG_OP='UPDATE' AND (TG_TABLE_NAME='task_history' OR
    (TG_TABLE_NAME='runtime_executions' AND old_row->>'state' IN ('succeeded','failed','cancelled','lost')
      AND old_row->'state'=new_row->'state' AND old_row->'ended_at' IS DISTINCT FROM new_row->'ended_at')) THEN
    SELECT source_key,payload,causation_id,occurred_at,project_id,workflow_id,agent_id
      INTO supersedes_key,previous_payload,previous_cause,previous_time,previous_project,previous_workflow,previous_agent
      FROM telemetry_outbox WHERE tenant_id=tenant AND source=TG_TABLE_NAME
        AND (source_key LIKE TG_TABLE_NAME||':'||(row_data->>'id')||':%'
          OR source_key='backfill:'||TG_TABLE_NAME||':'||(row_data->>'id')) ORDER BY id DESC LIMIT 1;
    IF supersedes_key IS NOT NULL THEN
      old_safe := COALESCE(previous_payload->'before','{}'::jsonb);
      project := previous_project; workflow := previous_workflow; agent := previous_agent;
      IF TG_TABLE_NAME='task_history' THEN
        happened_at := CASE WHEN old_row->'created_at' IS DISTINCT FROM new_row->'created_at'
          THEN telemetry_timestamp(new_row->>'created_at',previous_time) ELSE previous_time END;
      END IF;
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(key),'[]'::jsonb) INTO changed FROM (
    SELECT key FROM jsonb_object_keys(old_safe || new_safe) key
    WHERE old_safe->key IS DISTINCT FROM new_safe->key
  ) fields;
  payload_data := jsonb_build_object('before',old_safe,'after',new_safe,'changed_fields',changed,
    'context',CASE WHEN task_row IS NULL AND entity_kind IN ('run','runtime_execution')
      THEN jsonb_build_object('project_id',project,'agent_id',agent,'task_id',task)
      WHEN task_row IS NULL OR (TG_TABLE_NAME = 'tasks' AND TG_OP = 'DELETE')
      THEN '{}'::jsonb ELSE telemetry_task_snapshot(task_row || jsonb_build_object('tenant_id',tenant)) END,
    'transaction_id',txid_current()::text,
    'outcome_agent_id',NULLIF(current_setting('agent_hq.telemetry_outcome_agent_id',true),'')::bigint);
  IF supersedes_key IS NOT NULL THEN payload_data := payload_data || jsonb_build_object(
    'supersedes_source_key',supersedes_key,'context',COALESCE(previous_payload->'context','{}'::jsonb),
    'outcome_agent_id',previous_payload->'outcome_agent_id',
    'historical_context_known',COALESCE(previous_payload->'historical_context_known','true'::jsonb)); END IF;
  -- An oversized declared schema cannot inflate every canonical mutation without
  -- bound. Preserve the lifecycle fact while making missing field proof explicit.
  IF octet_length(payload_data::text) > 262144 THEN
    payload_data := jsonb_build_object('before',telemetry_pick(old_safe,ARRAY['id','status','project_id','workflow_id','task_type']),
      'after',telemetry_pick(new_safe,ARRAY['id','status','project_id','workflow_id','task_type']),
      'changed_fields',changed,'fields_complete',false,'truncated',true);
  END IF;
  outbox_id := nextval(pg_get_serial_sequence('telemetry_outbox','id'));
  key_text := TG_TABLE_NAME || ':' || COALESCE((row_data->>'id'),md5(row_data::text)) || ':' || outbox_id::text;
  INSERT INTO telemetry_outbox(id,tenant_id,source,source_key,entity_type,entity_id,task_id,
    project_id,workflow_id,agent_id,kind,occurred_at,causation_id,payload)
  VALUES(outbox_id,tenant,TG_TABLE_NAME,key_text,entity_kind,COALESCE(entity,workflow,project,tenant),task,
    project,workflow,agent,event_kind,happened_at,
    COALESCE(NULLIF(current_setting('agent_hq.telemetry_causation_id',true),''),previous_cause),payload_data);

  IF TG_TABLE_NAME='tasks' AND TG_OP='UPDATE' AND
    (old_row->'status' IS DISTINCT FROM new_row->'status' OR old_row->'workflow_id' IS DISTINCT FROM new_row->'workflow_id') THEN
    SELECT array_agg(blocked_id) INTO affected_ids FROM task_dependencies WHERE blocker_id=task;
  ELSIF TG_TABLE_NAME='task_dependencies' THEN
    affected_ids := ARRAY[task];
  ELSIF TG_TABLE_NAME IN ('workflow_task_statuses','workflow_type_task_statuses') AND
    (TG_OP<>'UPDATE' OR old_row->'terminal' IS DISTINCT FROM new_row->'terminal' OR old_row->'status_key' IS DISTINCT FROM new_row->'status_key') THEN
    SELECT array_agg(DISTINCT d.blocked_id) INTO affected_ids FROM task_dependencies d
      JOIN tasks t ON t.id=d.blocked_id WHERE t.tenant_id=tenant;
  END IF;
  IF affected_ids IS NOT NULL THEN
    PERFORM telemetry_refresh_dependencies(affected_ids,'dependency-effect:'||outbox_id,
      NULLIF(current_setting('agent_hq.telemetry_causation_id',true),''));
  END IF;
  RETURN NULL;
END $$;

--
-- Name: telemetry_capture_outcome_evidence(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_capture_outcome_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.outcome_evidence := telemetry_outcome_evidence(NEW.payload);
  RETURN NEW;
END $$;

--
-- Name: telemetry_capture_outcome_identity(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_capture_outcome_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE task_data jsonb; identity text; previous jsonb;
BEGIN
  IF NEW.kind='task.outcome' AND NEW.provenance='observed' THEN
    SELECT to_jsonb(t) INTO task_data FROM tasks t WHERE tenant_id=NEW.tenant_id AND id=NEW.task_id;
    IF NEW.payload->>'supersedes_source_key' IS NOT NULL THEN
      SELECT payload INTO previous FROM telemetry_outbox WHERE tenant_id=NEW.tenant_id AND source_key=NEW.payload->>'supersedes_source_key';
      IF previous->'after'->'outcome'=NEW.payload->'after'->'outcome' THEN identity:=previous->'after'->>'outcome_identity';
      ELSE
        SELECT generation::text INTO identity FROM telemetry_signal_generations
          WHERE tenant_id=NEW.tenant_id AND kind='outcome' AND signal_key=NEW.payload->'after'->>'outcome'
            AND source_scope->>'workflow_type_key'=NEW.payload->'context'->>'workflow_type'
            AND (COALESCE(source_scope->>'task_type','')='' OR source_scope->>'task_type'=NEW.payload->'context'->>'task_type')
            AND created_at<=NEW.occurred_at AND (retired_at IS NULL OR retired_at>NEW.occurred_at)
          ORDER BY CASE WHEN source_scope->>'task_type'=NEW.payload->'context'->>'task_type' THEN 0 ELSE 1 END,created_at DESC LIMIT 1;
      END IF;
    ELSE identity:=telemetry_signal_identity(task_data,'outcome',NEW.payload->'after'->>'outcome'); END IF;
    NEW.payload:=jsonb_set(NEW.payload,'{after,outcome_identity}',COALESCE(to_jsonb(identity),'null'::jsonb));
  END IF;
  RETURN NEW;
END $$;

--
-- Name: telemetry_dependency_state(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_dependency_state(row_data jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'unresolved_dependencies',CASE WHEN COALESCE(bool_and(COALESCE(b.tenant_id=(row_data->>'tenant_id')::bigint,false)),true)
      THEN COUNT(*) FILTER (WHERE COALESCE(ws.terminal,ts.terminal,gs.terminal,0)<>1) ELSE NULL END,
    'dependencies_within_project',COALESCE(bool_and(b.project_id IS NOT DISTINCT FROM (row_data->>'project_id')::bigint),true),
    'dependencies_within_tenant',COALESCE(bool_and(COALESCE(b.tenant_id=(row_data->>'tenant_id')::bigint,false)),true))
  FROM task_dependencies d JOIN tasks b ON b.id=d.blocker_id JOIN workflows s ON s.id=b.workflow_id
  LEFT JOIN LATERAL (SELECT terminal FROM workflow_task_statuses
    WHERE workflow_id=b.workflow_id AND status_key=b.status ORDER BY id DESC LIMIT 1) ws ON true
  LEFT JOIN LATERAL (SELECT terminal FROM workflow_type_task_statuses WHERE workflow_type_key=s.workflow_type
    AND status_key=b.status AND (tenant_id=b.tenant_id OR tenant_id IS NULL)
    ORDER BY CASE WHEN tenant_id IS NULL THEN 0 ELSE 1 END DESC,id DESC LIMIT 1) ts ON true
  LEFT JOIN task_statuses gs ON gs.name=b.status
  WHERE d.blocked_id=(row_data->>'id')::bigint
$$;

--
-- Name: telemetry_discarded_ancestry(bigint, text[]); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_discarded_ancestry(owner_tenant bigint, root_keys text[]) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE discarded(source_key) AS (
    SELECT unnest(root_keys)
    UNION
    SELECT COALESCE(o.payload->>'supersedes_source_key',r.payload->>'supersedes_source_key')
    FROM discarded d LEFT JOIN telemetry_outbox o ON o.tenant_id=owner_tenant AND o.source_key=d.source_key
    LEFT JOIN telemetry_observations r ON r.tenant_id=owner_tenant AND r.source_key=d.source_key
    WHERE COALESCE(o.payload->>'supersedes_source_key',r.payload->>'supersedes_source_key') IS NOT NULL
  ) SELECT COALESCE(array_agg(source_key),ARRAY[]::text[]) FROM discarded
$$;

--
-- Name: telemetry_expand_sources(bigint, jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_expand_sources(selected_tenant bigint, roots jsonb) RETURNS TABLE(source_type text, source_id bigint, project_id bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE sources AS (
    SELECT c.* FROM jsonb_to_recordset(roots) AS r(source_type text,source_id bigint)
      JOIN telemetry_source_context c USING(source_type,source_id) WHERE c.tenant_id=selected_tenant
    UNION
    SELECT c.* FROM sources s JOIN telemetry_source_context c
      ON c.source_type=s.parent_type AND c.source_id=s.parent_id AND c.tenant_id=selected_tenant
  ) SELECT source_type,source_id,project_id FROM sources
$$;

--
-- Name: telemetry_invalidate_source(bigint, text, bigint, boolean); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_invalidate_source(selected_tenant bigint, selected_type text, selected_id bigint, deleted boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF selected_tenant IS NULL THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('telemetry-proof:'||selected_tenant::text,0));
  IF deleted THEN
    DELETE FROM telemetry_query_results q USING telemetry_query_sources s
      WHERE q.tenant_id=selected_tenant AND s.tenant_id=selected_tenant
        AND s.query_id=q.id AND s.source_type=selected_type AND s.source_id=selected_id;
    RETURN;
  END IF;
  WITH affected AS MATERIALIZED (
    SELECT DISTINCT query_id FROM telemetry_query_sources
      WHERE tenant_id=selected_tenant AND source_type=selected_type AND source_id=selected_id
  ), canonical AS MATERIALIZED (
    SELECT source_type,source_id,project_id FROM telemetry_source_context
      WHERE tenant_id=selected_tenant
  ), revoked AS MATERIALIZED (
    SELECT DISTINCT s.query_id FROM telemetry_query_sources s JOIN affected a USING(query_id)
      LEFT JOIN canonical c ON c.source_type=s.source_type AND c.source_id=s.source_id
      WHERE s.tenant_id=selected_tenant
        AND (c.source_id IS NULL OR c.project_id IS DISTINCT FROM s.project_id)
  )
  DELETE FROM telemetry_query_results q USING revoked r
    WHERE q.tenant_id=selected_tenant AND q.id=r.query_id;
END;
$$;

--
-- Name: telemetry_json(text); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_json(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN COALESCE(raw::jsonb, '{}'::jsonb);
EXCEPTION WHEN invalid_text_representation THEN RETURN '{}'::jsonb;
END $$;

--
-- Name: telemetry_outcome_evidence(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_outcome_evidence(data jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT telemetry_pick(data, ARRAY['supersedes_source_key']) || jsonb_build_object(
    'before', telemetry_pick(CASE WHEN jsonb_typeof(data->'before')='object' THEN data->'before' ELSE '{}'::jsonb END, ARRAY['project_id','outcome','outcome_identity']),
    'after', telemetry_pick(CASE WHEN jsonb_typeof(data->'after')='object' THEN data->'after' ELSE '{}'::jsonb END, ARRAY['project_id','outcome','outcome_identity']),
    'context', telemetry_pick(CASE WHEN jsonb_typeof(data->'context')='object' THEN data->'context' ELSE '{}'::jsonb END, ARRAY['project_id','outcome','outcome_identity'])
  )
$$;

--
-- Name: telemetry_pick(jsonb, text[]); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_pick(row_data jsonb, keys text[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
  FROM jsonb_each(row_data) WHERE key = ANY(keys)
$$;

--
-- Name: telemetry_purge_task_results(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_purge_task_results() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM telemetry_invalidate_source(OLD.tenant_id,'tasks',OLD.id,true);
  RETURN OLD;
END;
$$;

--
-- Name: telemetry_refresh_dependencies(bigint[], text, text); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_refresh_dependencies(affected_ids bigint[], source_prefix text, cause text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE target record; after_state jsonb; before_state jsonb; prior_count jsonb; prior_scope jsonb; row_id bigint;
BEGIN
  FOR target IN SELECT t.* FROM tasks t WHERE t.id=ANY(affected_ids) AND t.tenant_id IS NOT NULL ORDER BY t.id LOOP
    -- Two different prerequisites can resolve concurrently. Serialize the
    -- dependent snapshot, without locking the dependent's canonical task row.
    PERFORM pg_advisory_xact_lock(hashtextextended('telemetry-dependencies:'||target.id,0));
    after_state := telemetry_task_snapshot(to_jsonb(target));
    IF octet_length(after_state::text)>100000 THEN
      after_state := telemetry_pick(after_state,ARRAY['id','status','project_id','workflow_id','workflow_type','task_type',
        'unresolved_dependencies','dependencies_within_project','dependencies_within_tenant']) || jsonb_build_object('fields_complete',false);
    END IF;
    SELECT payload->'after'->'unresolved_dependencies',payload->'after'->'dependencies_within_project'
      INTO prior_count,prior_scope FROM telemetry_outbox
      WHERE tenant_id=target.tenant_id AND task_id=target.id AND entity_type='task'
        AND payload->'after' ? 'unresolved_dependencies' ORDER BY id DESC LIMIT 1;
    IF prior_count IS NOT DISTINCT FROM after_state->'unresolved_dependencies'
      AND prior_scope IS NOT DISTINCT FROM after_state->'dependencies_within_project' THEN CONTINUE; END IF;
    before_state := after_state || jsonb_build_object('unresolved_dependencies',prior_count,
      'dependencies_within_project',prior_scope);
    row_id := nextval(pg_get_serial_sequence('telemetry_outbox','id'));
    INSERT INTO telemetry_outbox(id,tenant_id,source,source_key,entity_type,entity_id,task_id,project_id,workflow_id,
      agent_id,kind,occurred_at,causation_id,payload)
    VALUES(row_id,target.tenant_id,'task_dependencies',source_prefix||':'||target.id,'task',target.id,target.id,
      target.project_id,target.workflow_id,target.agent_id,'task.dependencies_changed',clock_timestamp(),cause,
      jsonb_build_object('before',before_state,'after',after_state,'context',after_state,
        'changed_fields',jsonb_build_array('unresolved_dependencies'),'dependency_history_complete',prior_count IS NOT NULL));
  END LOOP;
END $$;

--
-- Name: telemetry_run_snapshot(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_run_snapshot(row_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE result jsonb; agent_snapshot jsonb;
BEGIN
  result := telemetry_pick(row_data, ARRAY['id','agent_id','task_id','status','created_at','dispatched_at',
    'completed_at','started_at','task_outcome','token_input','token_output','token_total',
    'effective_model','effective_thinking_level','effective_fast_mode','failure_class','failure_stage',
    'runtime_ended_at','runtime_end_success','runtime_end_source','lifecycle_outcome_posted_at',
    'runtime_completed_at','lifecycle_handoff_status','semantic_outcome_missing']);
  SELECT jsonb_build_object('instructions_version',a.instructions_version,
    'instructions_fingerprint',md5(a.job_instructions),'runtime_type',a.runtime_type)
    INTO agent_snapshot FROM agents a
    WHERE a.id = (row_data->>'agent_id')::bigint AND a.tenant_id = (row_data->>'tenant_id')::bigint;
  RETURN result || jsonb_build_object('agent_config_at_observation',agent_snapshot);
END $$;

--
-- Name: telemetry_schema_snapshot(text); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_schema_snapshot(raw text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('fields',COALESCE(jsonb_agg(telemetry_pick(value,
    ARRAY['key','type','label','options','required','system'])),'[]'::jsonb))
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(telemetry_json(raw)->'fields')='array'
    THEN telemetry_json(raw)->'fields' ELSE '[]'::jsonb END)
  WHERE jsonb_typeof(value)='object'
$$;

--
-- Name: telemetry_signal_identity(jsonb, text, text); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_signal_identity(task_data jsonb, signal_kind text, signal_name text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE owner_tenant bigint:=(task_data->>'tenant_id')::bigint; workflow bigint:=(task_data->>'workflow_id')::bigint;
  selected_workflow_type text; selected_table text; selected_id text; identity text;
BEGIN
  IF signal_name IS NULL THEN RETURN NULL; END IF;
  SELECT workflow_type INTO selected_workflow_type FROM workflows WHERE id=workflow AND tenant_id=owner_tenant;
  IF signal_kind='status' THEN
    SELECT 'workflow_task_statuses',id::text INTO selected_table,selected_id FROM workflow_task_statuses WHERE workflow_id=workflow AND status_key=signal_name ORDER BY id DESC LIMIT 1;
    IF selected_id IS NULL THEN
      SELECT 'workflow_type_task_statuses',id::text INTO selected_table,selected_id FROM workflow_type_task_statuses
        WHERE tenant_id=owner_tenant AND workflow_type_key=selected_workflow_type AND status_key=signal_name ORDER BY id DESC LIMIT 1;
    END IF;
    IF selected_id IS NULL THEN SELECT 'task_statuses',name INTO selected_table,selected_id FROM task_statuses WHERE name=signal_name; END IF;
  ELSE
    SELECT 'workflow_type_outcomes',id::text INTO selected_table,selected_id FROM workflow_type_outcomes
      WHERE tenant_id=owner_tenant AND workflow_type_key=selected_workflow_type AND outcome_key=signal_name
        AND (task_type IS NULL OR task_type='' OR task_type=task_data->>'task_type')
      ORDER BY CASE WHEN task_type=task_data->>'task_type' THEN 0 ELSE 1 END,id DESC LIMIT 1;
  END IF;
  IF selected_id IS NULL THEN RETURN 'unregistered:'||signal_kind||':'||signal_name; END IF;
  SELECT generation::text INTO identity FROM telemetry_signal_generations WHERE source_table=selected_table AND source_id=selected_id AND active
    AND EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname=selected_table
      AND t.tgname='telemetry_signal_generation' AND t.tgenabled IN ('O','A'));
  -- A disabled or missing producer is unknown, not an unregistered raw key.
  RETURN identity;
END $$;

--
-- Name: telemetry_sync_schema_generations(bigint, bigint, text); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_sync_schema_generations(owner_tenant bigint, owner_schema bigint, raw_schema text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE field jsonb; fields jsonb; field_name text; field_kind text; seen text[] := ARRAY[]::text[];
BEGIN
  IF owner_tenant IS NULL THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('telemetry:catalog:'||owner_tenant,0));
  fields := CASE WHEN jsonb_typeof(telemetry_json(raw_schema)->'fields')='array'
    THEN telemetry_json(raw_schema)->'fields' ELSE '[]'::jsonb END;
  FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP
    field_name := field->>'key'; field_kind := COALESCE(field->>'type','text');
    IF field_name IS NULL OR field_name='' OR NOT field_kind IN ('text','textarea','url','select','number','checkbox') THEN CONTINUE; END IF;
    seen := array_append(seen,field_name);
    INSERT INTO telemetry_field_generations(tenant_id,schema_id,field_key,field_type)
    VALUES(owner_tenant,owner_schema,field_name,field_kind)
    ON CONFLICT(tenant_id,schema_id,field_key) DO UPDATE SET
      generation=CASE WHEN telemetry_field_generations.active AND telemetry_field_generations.field_type=EXCLUDED.field_type
        THEN telemetry_field_generations.generation ELSE gen_random_uuid() END,
      field_type=EXCLUDED.field_type,active=true,updated_at=clock_timestamp();
  END LOOP;
  UPDATE telemetry_field_generations SET active=false,updated_at=clock_timestamp()
    WHERE tenant_id=owner_tenant AND schema_id=owner_schema AND active AND NOT field_key=ANY(seen);
  UPDATE telemetry_catalog_entries entry SET retired_at=clock_timestamp()
    WHERE entry.tenant_id=owner_tenant AND entry.retired_at IS NULL
      AND entry.descriptor->'source'->>'schema_id'=owner_schema::text
      AND NOT EXISTS(SELECT 1 FROM telemetry_field_generations generation
        WHERE generation.tenant_id=owner_tenant AND generation.schema_id=owner_schema
          AND generation.field_key=entry.descriptor->'source'->>'field_key' AND generation.active
          AND generation.generation::text=entry.descriptor->'source'->>'generation');
END $$;

--
-- Name: telemetry_sync_signal_generation(text, jsonb, boolean); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_sync_signal_generation(source_name text, row_data jsonb, is_deleted boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE source_key text; owner_tenant bigint; signal_kind text; signal_name text; identity_scope jsonb;
  previous telemetry_signal_generations%ROWTYPE; is_enabled boolean := true;
BEGIN
  signal_kind:=CASE WHEN source_name='workflow_type_outcomes' THEN 'outcome' ELSE 'status' END;
  source_key:=CASE WHEN source_name='task_statuses' THEN row_data->>'name' ELSE row_data->>'id' END;
  signal_name:=COALESCE(row_data->>'status_key',row_data->>'outcome_key',row_data->>'name');
  owner_tenant:=(row_data->>'tenant_id')::bigint;
  IF source_name='workflow_task_statuses' THEN SELECT tenant_id INTO owner_tenant FROM workflows WHERE id=(row_data->>'workflow_id')::bigint; END IF;
  identity_scope:=telemetry_pick(row_data,ARRAY['tenant_id','workflow_id','workflow_type_key','task_type']);
  is_enabled:=NOT is_deleted AND COALESCE(row_data->>'enabled','1')<>'0' AND COALESCE(row_data->>'behavior','')<>'disable';
  -- One global lock orders global and tenant signal writes with catalog reads.
  PERFORM pg_advisory_xact_lock(hashtextextended('telemetry:signals',0));
  SELECT * INTO previous FROM telemetry_signal_generations WHERE source_table=source_name AND source_id=source_key AND active FOR UPDATE;
  IF previous.generation IS NOT NULL AND (NOT is_enabled OR previous.signal_key<>signal_name
    OR previous.tenant_id IS DISTINCT FROM owner_tenant OR previous.source_scope<>identity_scope) THEN
    UPDATE telemetry_signal_generations SET active=false,retired_at=clock_timestamp() WHERE generation=previous.generation;
    UPDATE telemetry_catalog_entries entry SET retired_at=clock_timestamp()
      WHERE entry.retired_at IS NULL AND entry.source_key='signal:'||previous.generation::text;
    previous.generation:=NULL;
  END IF;
  IF is_enabled AND previous.generation IS NULL THEN
    INSERT INTO telemetry_signal_generations(source_table,source_id,tenant_id,kind,signal_key,source_scope)
      VALUES(source_name,source_key,owner_tenant,signal_kind,signal_name,identity_scope);
  END IF;
END $$;

--
-- Name: telemetry_task_snapshot(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_task_snapshot(row_data jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT telemetry_task_snapshot_without_signal_identities(row_data) || jsonb_build_object('status_identity',
    CASE WHEN EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='telemetry_task_status_identity' AND tgenabled IN ('O','A'))
      AND ((row_data->>'telemetry_status_identity')='unregistered:status:'||(row_data->>'status')
        OR EXISTS(SELECT 1 FROM telemetry_signal_generations WHERE generation::text=row_data->>'telemetry_status_identity'
          AND kind='status' AND signal_key=row_data->>'status')) THEN row_data->>'telemetry_status_identity' ELSE NULL END)
$$;

--
-- Name: telemetry_task_snapshot_without_generations(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_task_snapshot_without_generations(row_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb; wf jsonb; schema_row record; descriptor jsonb;
  descriptors jsonb := '{}'::jsonb; custom_values jsonb := '{}'::jsonb;
  raw_custom jsonb; field_key text; field_value jsonb; incomplete boolean := false;
BEGIN
  result := telemetry_pick(row_data, ARRAY['id','status','priority','story_points','retry_count',
    'total_dispatch_count','manual_intervention_count','created_at','updated_at','project_id',
    'task_type','agent_id','assigned_agent_id','active_instance_id','origin_task_id','paused_at']);
  result := result || jsonb_build_object('title',left(row_data->>'title',8192)) || telemetry_dependency_state(row_data);
  SELECT to_jsonb(s) INTO wf FROM workflows s
    WHERE id = (row_data->>'workflow_id')::bigint AND tenant_id = (row_data->>'tenant_id')::bigint;
  result := result || jsonb_build_object('workflow_id',row_data->'workflow_id',
    'workflow_type',wf->'workflow_type','workflow_status',wf->'status');
  FOR schema_row IN SELECT id, schema_json FROM task_field_schemas
    WHERE tenant_id = (row_data->>'tenant_id')::bigint
      AND workflow_type_key = wf->>'workflow_type'
      AND (task_type IS NULL OR task_type = row_data->>'task_type')
    ORDER BY task_type NULLS FIRST, id
  LOOP
    IF jsonb_typeof(telemetry_json(schema_row.schema_json)->'fields') = 'array' THEN
      FOR descriptor IN SELECT value FROM jsonb_array_elements(telemetry_json(schema_row.schema_json)->'fields') LOOP
        field_key := descriptor->>'key';
        IF field_key IS NOT NULL AND COALESCE(descriptor->>'type','text') IN ('text','textarea','url','select','number','checkbox') THEN
          descriptors := descriptors || jsonb_build_object(field_key,
            telemetry_pick(descriptor, ARRAY['key','type','label','options']) || jsonb_build_object(
              'type',COALESCE(descriptor->>'type','text'),'schema_id',schema_row.id,'schema_fingerprint',md5(schema_row.schema_json)));
        END IF;
      END LOOP;
    END IF;
  END LOOP;
  raw_custom := telemetry_json(row_data->>'custom_fields_json');
  FOR field_key, descriptor IN SELECT key,value FROM jsonb_each(descriptors) LOOP
    field_value := raw_custom->field_key;
    IF jsonb_typeof(field_value) IN ('string','number','boolean','null') THEN
      IF octet_length(field_value::text) <= 8192 THEN
        custom_values := custom_values || jsonb_build_object(field_key,
          CASE WHEN descriptor->>'type'='number' AND jsonb_typeof(field_value)='number'
            THEN jsonb_build_object('decimal',field_value::text) ELSE field_value END);
      ELSE incomplete := true;
      END IF;
    ELSIF field_value IS NOT NULL THEN incomplete := true;
    END IF;
  END LOOP;
  IF jsonb_typeof(raw_custom) IS DISTINCT FROM 'object' THEN incomplete := true; END IF;
  RETURN result || jsonb_build_object('custom_fields',custom_values,'field_descriptors',
    (SELECT COALESCE(jsonb_agg(value),'[]'::jsonb) FROM jsonb_each(descriptors)),
    'fields_complete',NOT incomplete);
END $$;

--
-- Name: telemetry_task_snapshot_without_signal_identities(jsonb); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_task_snapshot_without_signal_identities(row_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE snapshot jsonb; descriptors jsonb;
BEGIN
  snapshot := telemetry_task_snapshot_without_generations(row_data);
  SELECT COALESCE(jsonb_agg(field.value || CASE WHEN generation.generation IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('generation',generation.generation::text) END),'[]'::jsonb)
    INTO descriptors
    FROM jsonb_array_elements(snapshot->'field_descriptors') field
    LEFT JOIN telemetry_field_generations generation ON generation.tenant_id=(row_data->>'tenant_id')::bigint
      AND generation.schema_id=(field.value->>'schema_id')::bigint AND generation.field_key=field.value->>'key'
      AND generation.field_type=field.value->>'type' AND generation.active;
  RETURN jsonb_set(snapshot,'{field_descriptors}',descriptors);
END $$;

--
-- Name: telemetry_timestamp(text, timestamp with time zone); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_timestamp(raw text, fallback timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
  IF raw IS NULL OR raw = '' THEN RETURN fallback; END IF;
  IF raw ~ '(Z|[+-][0-9]{2}:?[0-9]{2})$' THEN RETURN raw::timestamptz; END IF;
  RETURN raw::timestamp AT TIME ZONE 'UTC';
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN fallback;
END $_$;

--
-- Name: telemetry_track_schema_generation(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_track_schema_generation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    PERFORM telemetry_sync_schema_generations(OLD.tenant_id,OLD.id,'{"fields":[]}');
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
    PERFORM telemetry_sync_schema_generations(OLD.tenant_id,OLD.id,'{"fields":[]}');
  END IF;
  PERFORM telemetry_sync_schema_generations(NEW.tenant_id,NEW.id,NEW.schema_json);
  RETURN NEW;
END $$;

--
-- Name: telemetry_track_signal_generation(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_track_signal_generation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN PERFORM telemetry_sync_signal_generation(TG_TABLE_NAME,to_jsonb(OLD),true);RETURN OLD; END IF;
  IF TG_OP='UPDATE' AND TG_TABLE_NAME='task_statuses' AND to_jsonb(OLD)->>'name' IS DISTINCT FROM to_jsonb(NEW)->>'name' THEN
    PERFORM telemetry_sync_signal_generation(TG_TABLE_NAME,to_jsonb(OLD),true);
  END IF;
  PERFORM telemetry_sync_signal_generation(TG_TABLE_NAME,to_jsonb(NEW));RETURN NEW;
END $$;

--
-- Name: telemetry_track_task_status_identity(); Type: FUNCTION; Schema: telemetry; Owner: -
--

CREATE FUNCTION telemetry.telemetry_track_task_status_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='INSERT' OR OLD.telemetry_status_identity IS NULL OR OLD.status IS DISTINCT FROM NEW.status
    OR OLD.workflow_id IS DISTINCT FROM NEW.workflow_id OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
    NEW.telemetry_status_identity:=telemetry_signal_identity(to_jsonb(NEW),'status',NEW.status);
  ELSE NEW.telemetry_status_identity:=OLD.telemetry_status_identity; END IF;
  RETURN NEW;
END $$;

