    CONSTRAINT workflows_environment_setup_mode CHECK (((jsonb_typeof(environment_setup) = 'object'::text) AND (environment_setup ? 'mode'::text) AND (jsonb_typeof((environment_setup -> 'mode'::text)) = 'string'::text) AND ((environment_setup ->> 'mode'::text) = ANY (ARRAY['off'::text, 'auto'::text, 'custom'::text])))),
    CONSTRAINT workflows_length_kind_check CHECK ((length_kind = ANY (ARRAY['time'::text, 'runs'::text]))),
    CONSTRAINT workflows_repo_access_mode_check CHECK ((repo_access_mode = ANY (ARRAY['worktree'::text, 'clone'::text]))),
