);

--
-- Name: telemetry_source_context; Type: VIEW; Schema: telemetry; Owner: -
--

CREATE VIEW telemetry.telemetry_source_context AS
 SELECT 'tasks'::text AS source_type,
    t.id AS source_id,
    t.tenant_id,
    t.project_id,
    'workflows'::text AS parent_type,
    t.workflow_id AS parent_id
   FROM tasks.tasks t
UNION ALL
 SELECT 'workflows'::text AS source_type,
    w.id AS source_id,
    w.tenant_id,
    w.project_id,
    'projects'::text AS parent_type,
    w.project_id AS parent_id
   FROM workflow.workflows w
UNION ALL
 SELECT 'projects'::text AS source_type,
    p.id AS source_id,
    p.tenant_id,
    p.id AS project_id,
    NULL::text AS parent_type,
    NULL::bigint AS parent_id
   FROM core.projects p
UNION ALL
 SELECT 'agents'::text AS source_type,
    a.id AS source_id,
    a.tenant_id,
    a.project_id,
    'projects'::text AS parent_type,
    a.project_id AS parent_id
   FROM agents.agents a
UNION ALL
 SELECT 'job_instances'::text AS source_type,
    j.id AS source_id,
    j.tenant_id,
    COALESCE(t.project_id, a.project_id) AS project_id,
        CASE
            WHEN (j.task_id IS NOT NULL) THEN 'tasks'::text
            ELSE 'agents'::text
        END AS parent_type,
    COALESCE(j.task_id, j.agent_id) AS parent_id
   FROM ((runs.job_instances j
     LEFT JOIN tasks.tasks t ON (((t.id = j.task_id) AND (t.tenant_id = j.tenant_id))))
     LEFT JOIN agents.agents a ON (((a.id = j.agent_id) AND (a.tenant_id = j.tenant_id))))
UNION ALL
 SELECT 'runtime_executions'::text AS source_type,
    r.id AS source_id,
    r.tenant_id,
    COALESCE(t.project_id, a.project_id) AS project_id,
    'job_instances'::text AS parent_type,
    j.id AS parent_id
   FROM (((runs.runtime_executions r
     JOIN runs.job_instances j ON (((j.id = r.instance_id) AND (j.tenant_id = r.tenant_id))))
     LEFT JOIN tasks.tasks t ON (((t.id = j.task_id) AND (t.tenant_id = j.tenant_id))))
     LEFT JOIN agents.agents a ON (((a.id = j.agent_id) AND (a.tenant_id = j.tenant_id))));

