CREATE TRIGGER openclaw_mcp_agent_changed AFTER UPDATE OF workspace_path, openclaw_agent_id, runtime_type, session_key, enabled, deleted_at ON agents.agents FOR EACH ROW WHEN (((old.workspace_path IS DISTINCT FROM new.workspace_path) OR (old.openclaw_agent_id IS DISTINCT FROM new.openclaw_agent_id) OR (old.runtime_type IS DISTINCT FROM new.runtime_type) OR (old.session_key IS DISTINCT FROM new.session_key) OR (old.enabled IS DISTINCT FROM new.enabled) OR (old.deleted_at IS DISTINCT FROM new.deleted_at))) EXECUTE FUNCTION agents.enqueue_openclaw_mcp_sync_for_agent();

